const inputItem = $input.first();
const rawText = inputItem.json.data || '';

const lines = rawText.split('\n').filter((l) => l.trim().length > 0);
const records = [];
let parseFailures = 0;
for (const line of lines) { try { records.push(JSON.parse(line)); } catch (e) { parseFailures++; } }

function keywordRegex(term, exact) {
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return exact ? new RegExp(`\\b${escaped}\\b`, 'i') : new RegExp(`\\b${escaped}\\w*`, 'i');
}

// --- FIX 2: hr_recruiting_automation co-occurrence requirement.
// See UOR-06-Build-Log.md for full rationale.
//
// V1 attempt (anywhere-in-record co-occurrence) was tried and REJECTED after
// dry-running against the real corpus: all 4 original false positives still
// fired, because long HN posts routinely mention "AI" or "system" SOMEWHERE
// unrelated to the hiring context -- e.g. a post saying "I do not use AI to
// screen your applications" (negated, and a keyword match can't see the
// negation) and "an airborne system" (a drone-defense system, nothing to do
// with recruiting). Anywhere-in-text matching is too loose for long,
// multi-topic posts.
//
// V2 (this version): the automation-signal keyword must appear in the SAME
// sentence/paragraph as the hiring/recruiting keyword, not just anywhere in
// the record. Text is split on paragraph breaks ('<p>', HN's own paragraph
// marker) and sentence-ending punctuation; the tag only fires if one single
// chunk contains both a topic keyword and an automation-signal keyword.
// Verified this eliminates all 4 real false positives while still firing on
// a genuine single-sentence automation-demand case (see build log for the
// synthetic test suite).
//
// 'software' is deliberately excluded from the automation-signal set: it
// collides with ubiquitous job titles ("Software Engineer") in exactly this
// corpus and would just recreate the bug under a different word. 'system'
// and 'app' are matched as EXACT whole words only: exact \bsystem\b does not
// match "systems" (as in "Systems Engineer"), and exact \bapp\b does not
// match "apply"/"application"/"applicant" (every job posting's own CTA).
const HR_AUTOMATION_SIGNAL_KEYWORDS = [['automate',false],['tool',false],['ai',true],['system',true],['app',true]];

function splitIntoChunks(text) {
  return text.split(/<p>|(?<=[.!?])\s+/).filter(Boolean);
}
// --- end FIX 2 ---

const TAGS = [
  { tag: 'customer_communication_automation', compliance: false, keywords: [['receptionist',false],['call answering',true],['chatbot',false],['live chat',true],['customer support',true],['helpdesk',false],['missed call',true]] },
  { tag: 'scheduling_appointment_automation', compliance: false, keywords: [['appointment',false],['booking',false],['calendar',false],['scheduling',false],['reservation',false]] },
  { tag: 'lead_gen_qualification', compliance: false, keywords: [['lead gen',true],['lead qualification',true],['cold outreach',true],['prospecting',false],['crm',true]] },
  { tag: 'content_creation_automation', compliance: false, keywords: [['content creation',true],['blog writing',true],['copywriting',false],['video editing',true],['faceless content',true],['script writing',true]] },
  { tag: 'social_media_management', compliance: false, keywords: [['social media',true],['instagram',false],['tiktok',false],['youtube shorts',true],['posting schedule',true]] },
  { tag: 'data_entry_extraction', compliance: false, keywords: [['data entry',true],['scraping',false],['extraction',false],['ocr',true],['document processing',true]] },
  { tag: 'ecommerce_operations', compliance: false, keywords: [['shopify',false],['e-commerce',true],['inventory',false],['order fulfillment',true],['dropshipping',false]] },
  { tag: 'marketing_advertising_automation', compliance: false, keywords: [['ad campaign',true],['email marketing',true],['newsletter',false],['seo',true],['marketing automation',true]] },
  { tag: 'freelance_gig_service_demand', compliance: false, keywords: [['fiverr',false],['upwork',false],['freelance',false],['gig work',true],['contract work',true]] },
  { tag: 'saas_app_dev_demand', compliance: false, keywords: [['build an app',true],['mvp',true],['saas idea',true],['no-code app',true],['want a tool that',true]] },
  { tag: 'financial_admin_automation', compliance: true, keywords: [['invoicing',false],['bookkeeping',false],['expense tracking',true],['billing',false],['payroll',false]] },
  { tag: 'hr_recruiting_automation', compliance: false, keywords: [['hiring',false],['recruiting',false],['resume screening',true],['onboarding',false]], requiresCoOccurrence: HR_AUTOMATION_SIGNAL_KEYWORDS },
  { tag: 'personal_productivity_ai', compliance: false, keywords: [['personal assistant',true],['task management',true],['note-taking',true],['productivity',false]] },
  { tag: 'real_estate_local_business_ops', compliance: false, keywords: [['realtor',false],['real estate agent',true],['real estate investor',true],['property management',true],['real estate market',true],['local business',true],['small business ops',true]] },
  { tag: 'healthcare_admin_ops', compliance: true, keywords: [['medical scheduling',true],['patient intake',true],['clinic',false]] },
  { tag: 'legal_admin_ops', compliance: true, keywords: [['contract review',true],['legal intake',true],['paralegal',false]] },
  { tag: 'tool_recommendation_seeking', compliance: false, keywords: [['alternative to',true],['alternatives to',true],['recommend a tool',true],['recommend software',true],['what tool',true],['what software',true],['best tool for',true],['looking for a tool',true],['web-based tool',true],['app that supports',true],['software that supports',true]] },
];

const clusters = {};
TAGS.forEach((t) => { clusters[t.tag] = { compliance: t.compliance, members: [] }; });

records.forEach((rec) => {
  const rs = rec.raw_signal || {};
  const text = `${rs.opportunity_title || ''} ${rs.problem || ''} ${rs.demand_signal || ''}`;
  TAGS.forEach((t) => {
    let hit;
    if (t.requiresCoOccurrence) {
      const chunks = splitIntoChunks(text);
      hit = chunks.some((chunk) => {
        const topicHit = t.keywords.some(([term, exact]) => keywordRegex(term, exact).test(chunk));
        const autoHit = t.requiresCoOccurrence.some(([term, exact]) => keywordRegex(term, exact).test(chunk));
        return topicHit && autoHit;
      });
    } else {
      hit = t.keywords.some(([term, exact]) => keywordRegex(term, exact).test(text));
    }
    if (hit) {
      clusters[t.tag].members.push({
        opportunity_id: rec.opportunity_id,
        source_name: rec.source,
        source_type: rec.source_type,
        date_discovered: rec.date_discovered,
        compliance_review_required: rec.compliance_review_required,
        title: rs.opportunity_title,
      });
    }
  });
});

const outputRows = [];
Object.entries(clusters).forEach(([tag, c]) => {
  if (c.members.length === 0) return;
  const freq = c.members.length;
  const sourceNames = new Set(c.members.map((m) => m.source_name));
  const sourceTypes = new Set(c.members.map((m) => m.source_type));
  const dates = c.members.map((m) => m.date_discovered).filter(Boolean).sort();
  const complianceCount = c.members.filter((m) => m.compliance_review_required === true).length;
  let status;
  if (freq === 1) status = 'SINGLE_OBSERVATION';
  else if (freq <= 4) status = 'EMERGING_PATTERN_CANDIDATE';
  else status = 'RECURRING_PATTERN';

  outputRows.push({
    tag,
    compliance_sensitive: c.compliance,
    frequency_count: freq,
    source_diversity_count: sourceNames.size,
    source_type_diversity: sourceTypes.size,
    first_seen_date: dates[0] || null,
    last_seen_date: dates[dates.length - 1] || null,
    compliance_flagged_member_count: complianceCount,
    member_opportunity_ids: c.members.map((m) => m.opportunity_id),
    representative_titles: c.members.slice(0, 3).map((m) => m.title),
    cluster_status: status,
    formula_version: 'uor06-v1-tag-cluster-2026-09-06',
    computed_at: new Date().toISOString(),
  });
});

const fileText = outputRows.map((r) => JSON.stringify(r)).join('\n') + '\n';

return [{
  json: {
    record_count: records.length,
    parse_failures: parseFailures,
    tags_with_hits: outputRows.length,
    total_tags_defined: TAGS.length,
    file_text: fileText,
  },
}];
